// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address newOwner) public {
        // Admissible domain: newOwner is any non-zero address
        vm.assume(newOwner != address(0));

        // Attempt to transfer ownership to the new non-zero address
        bool success;
        try c.transferOwnership(newOwner) {
            success = true;
        } catch {
            success = false;
        }

        // The reference contract should succeed for any non-zero address;
        // the buggy contract requires newOwner == address(0) and reverts here.
        assertTrue(success);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.assume(newOwner != address(0));
        vm.assume(newOwner != address(this));
        address originalOwner = c.owner();
        vm.prank(caller);
        c.transferOwnership(newOwner);
        address afterOwner = c.owner();
        assertTrue(afterOwner == originalOwner || caller == originalOwner);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address newOwner, address caller) public {
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(this));
        address oldOwner = c.owner();
        vm.prank(caller);
        c.transferOwnership(newOwner);
        if (caller == oldOwner) {
            assertEq(c.owner(), newOwner);
        } else {
            assertEq(c.owner(), oldOwner);
        }
    }
}

