pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        vm.assume(nonOwner != address(this));
        vm.assume(nonOwner != address(0));
        vm.assume(newOwner != address(0));
        address ownerBefore = c.owner();
        vm.prank(nonOwner);
        try c.transferOwnership(newOwner) {} catch {}
        address ownerAfter = c.owner();
        assertTrue(ownerAfter == ownerBefore);
    }
}

